import sys

def main():
    s = sys.stdin.read().split()[0]
    val = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    prev = 0
    for ch in reversed(s):
        v = val[ch]
        if v < prev:
            total -= v
        else:
            total += v
            prev = v
    print(total)

